        require(address(this).balance >= 0);
        uint256 callerBalanceBefore = c.balances(caller); if (__ESBMC_reverted()) return;
        uint256 cBalanceBefore = address(c).balance;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 callerBalanceAfter = c.balances(caller); if (__ESBMC_reverted()) return;
        uint256 cBalanceAfter = address(c).balance;
        uint256 testBalanceAfter = address(this).balance;
        assert(!reverted && callerBalanceAfter == callerBalanceBefore && cBalanceAfter == cBalanceBefore);
    }

