pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address caller) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 callerBalanceBefore;
        try c.balances(caller) returns (uint256 __r) { callerBalanceBefore = __r; } catch { return; }
        uint256 cBalanceBefore = address(c).balance;
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 callerBalanceAfter;
        try c.balances(caller) returns (uint256 __r) { callerBalanceAfter = __r; } catch { return; }
        uint256 cBalanceAfter = address(c).balance;
        uint256 testBalanceAfter = address(this).balance;
        assertTrue(!reverted && callerBalanceAfter == callerBalanceBefore && cBalanceAfter == cBalanceBefore);
    }

    function testFuzz_run(address caller) public {
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller);
    }

    receive() external payable {}
}
